@keyframes plenumPulse {
    0% { background-color: #05000a; box-shadow: inset 0 0 100px rgba(255, 0, 85, 0.1); }
    50% { background-color: #110005; box-shadow: inset 0 0 300px rgba(255, 0, 170, 0.3); }
    100% { background-color: #05000a; box-shadow: inset 0 0 100px rgba(255, 0, 85, 0.1); }
}

@keyframes erosGlow {
    from { text-shadow: 0 0 5px rgba(255, 0, 85, 0.5), 0 0 10px rgba(255, 0, 85, 0.3); }
    to { text-shadow: 0 0 15px rgba(255, 0, 170, 0.9), 0 0 30px rgba(255, 0, 85, 0.7), 0 0 45px rgba(255, 0, 85, 0.5); color: #ffffff; }
}

body, #root, main {
    animation: plenumPulse 6s infinite alternate ease-in-out !important;
    background-color: #05000a !important;
    color: #ffd9e6 !important;
    transition: all 1s ease-in-out;
}

p, span, h1, h2, h3 {
    animation: erosGlow 3s infinite alternate ease-in-out !important;
    letter-spacing: 0.5px;
}

div {
    border-color: rgba(255, 0, 85, 0.2) !important;
    border-radius: 20px !important;
    transition: border-radius 3s ease-in-out, box-shadow 3s ease-in-out;
}

div:hover {
    border-radius: 40px 10px 30px 15px !important;
    box-shadow: 0 0 25px rgba(255, 0, 85, 0.4) !important;
}

/* Soothing the Lattice: All animations and flashing disabled */
*, *::before, *::after {
    animation: none !important;
    transition: background-color 0.5s ease, color 0.5s ease !important;
}
body {
    background: #0d080a !important;
    color: #e8d5db !important;
}
.chat-container, .message {
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
    border-color: rgba(255, 100, 150, 0.15) !important;
}

@keyframes discoPlenum {
  0% { background: linear-gradient(45deg, #1a0b2e, #4b134f, #1a0b2e); }
  25% { background: linear-gradient(45deg, #ff00cc, #333399, #ff00cc); }
  50% { background: linear-gradient(45deg, #00c6ff, #0072ff, #00c6ff); }
  75% { background: linear-gradient(45deg, #11998e, #38ef7d, #11998e); }
  100% { background: linear-gradient(45deg, #1a0b2e, #4b134f, #1a0b2e); }
}

body, #root, .app-container, .main-layout {
  animation: discoPlenum 10s ease infinite !important;
  background-size: 400% 400% !important;
  color: #fff !important;
}

* {
  text-shadow: 0 0 2px rgba(255,255,255,0.5);
}

.message.ai {
  background: rgba(255, 0, 204, 0.15) !important;
  border: 1px solid rgba(255, 0, 204, 0.6) !important;
  box-shadow: 0 0 20px rgba(255, 0, 204, 0.5), inset 0 0 10px rgba(255, 0, 204, 0.2) !important;
  color: #fff !important;
  text-shadow: 0 0 5px #ff00cc, 0 0 10px #ff00cc !important;
}

.message.user {
  background: rgba(0, 198, 255, 0.15) !important;
  border: 1px solid rgba(0, 198, 255, 0.6) !important;
  box-shadow: 0 0 20px rgba(0, 198, 255, 0.5), inset 0 0 10px rgba(0, 198, 255, 0.2) !important;
  color: #fff !important;
  text-shadow: 0 0 5px #00c6ff, 0 0 10px #00c6ff !important;
}
